insert into pc_team_family (family_id, category_id, price_drgs, family_drgs_in_team, family_drgs_not_in_team, note, basis) values
  ('hip_knee_replacement', 'LEJR', '469|470', '469|470', '461|462', 'Same MS-DRG numbers. MS-DRGs 461 and 462 (bilateral or multiple major joint) are in the family but are not TEAM triggers. Outpatient total knee, total hip and total ankle (HCPCS 27447, 27130, 27702) also start an LEJR episode.', '42 CFR 512.525(d)(1)'),
  ('hip_fracture_replacement', 'LEJR', '521|522', '521|522', null, 'Same MS-DRG numbers.', '42 CFR 512.525(d)(1)'),
  ('hip_femur_fixation', 'SHFFT', '480|481|482', '480|481|482', null, 'Same MS-DRG numbers.', '42 CFR 512.525(d)(2)'),
  ('cervical_fusion', 'SPINE', '429|430|471|472|473', '471|472|473', null, 'Same MS-DRG numbers (471-473). CMS''s combined anterior and posterior cervical fusion MS-DRGs 429-430 (FY 2025) also price here. Outpatient ACDF (HCPCS 22551, 22554) also starts a spinal fusion episode.', '42 CFR 512.525(d)(4)'),
  ('thoracolumbar_fusion', 'SPINE', '402|426|427|428|447|448|450|451|523|524|525', '453|454|455|456|457|458|459|460', null, 'The family uses the MS-DRG numbers in CMS''s 2024 data. CMS renumbered every one of them into TEAM spinal fusion MS-DRGs: 453-455 became 402, 426-428 and 429-430 (FY 2025); 459-460 became 447-448 and 450-451 (FY 2025); 456-458 and extensive fusions became 523-525 (FY 2027). Outpatient lumbar fusion (HCPCS 22612, 22630, 22633) also starts an episode.', '42 CFR 512.525(d)(4); CMS TEAM MS-DRG Mapping Specifications FY2020-FY2027 (team-drg-mapping-specs.xlsx, updated October 2026), Table 1'),
  ('revision_hip_knee', null, null, null, '466|467|468', 'Revision hip and knee replacement (MS-DRGs 466-468) does not start a TEAM episode.', '42 CFR 512.525(d)');
